import{_ as s,o as n,c as i,a2 as e}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"Agent 开发框架：LangChain、CrewAI 等框架的位置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/01-agent-basics/agent-frameworks.md","filePath":"zh/learn/01-agent-basics/agent-frameworks.md","lastUpdated":1792545482000}'),l={name:"zh/learn/01-agent-basics/agent-frameworks.md"};function p(t,a,h,r,o,d){return n(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="agent-开发框架-langchain、crewai-等框架的位置" tabindex="-1">Agent 开发框架：LangChain、CrewAI 等框架的位置 <a class="header-anchor" href="#agent-开发框架-langchain、crewai-等框架的位置" aria-label="Permalink to &quot;Agent 开发框架：LangChain、CrewAI 等框架的位置&quot;">​</a></h1><h2 id="一、为什么会出现-agent-框架" tabindex="-1">一、为什么会出现 Agent 框架？ <a class="header-anchor" href="#一、为什么会出现-agent-框架" aria-label="Permalink to &quot;一、为什么会出现 Agent 框架？&quot;">​</a></h2><p>最开始开发一个 Agent，可能只需要完成几个步骤：</p><ol><li>调用模型。</li><li>解析模型的工具调用请求。</li><li>执行工具。</li><li>把结果返回模型。</li><li>生成最终回答。</li></ol><p>但随着系统变复杂，开发者还需要处理：</p><ul><li>多轮工具调用。</li><li>多步骤任务规划。</li><li>对话状态和记忆。</li><li>工具执行错误。</li><li>工作流分支。</li><li>人工审批。</li><li>长时间运行任务。</li><li>执行日志和调试。</li><li>多个 Agent 之间的协作。</li></ul><p>如果所有逻辑都从零开始编写，代码会越来越复杂。</p><p>Agent 框架的作用，就是提供一组可复用的抽象和基础能力，降低开发复杂 Agent 的成本。</p><p><strong>框架可以帮助组织 Agent，但不会自动保证 Agent 的正确性、安全性或业务价值。</strong></p><h2 id="二、agent-框架在整个系统中的位置" tabindex="-1">二、Agent 框架在整个系统中的位置 <a class="header-anchor" href="#二、agent-框架在整个系统中的位置" aria-label="Permalink to &quot;二、Agent 框架在整个系统中的位置&quot;">​</a></h2><p>一个典型的 Agent 应用可以拆成以下层次：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户 / 业务系统</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>应用业务逻辑</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>Agent 框架 / Agent Runtime</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>模型 API</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>模型服务</span></span></code></pre></div><p>Agent 框架还可能负责连接：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Runtime</span></span>
<span class="line"><span> ├── Tools</span></span>
<span class="line"><span> ├── MCP Clients</span></span>
<span class="line"><span> ├── Memory</span></span>
<span class="line"><span> ├── Workflow</span></span>
<span class="line"><span> ├── State</span></span>
<span class="line"><span> └── Observability</span></span></code></pre></div><p>这些模块的具体边界取决于框架和应用设计，并不是所有框架都包含全部能力。</p><p>更重要的是，业务权限、数据库事务、资金限制等关键规则，不应该仅仅依赖框架约定。</p><h2 id="三、常见-agent-开发框架" tabindex="-1">三、常见 Agent 开发框架 <a class="header-anchor" href="#三、常见-agent-开发框架" aria-label="Permalink to &quot;三、常见 Agent 开发框架&quot;">​</a></h2><h3 id="_1-langchain" tabindex="-1">1. LangChain <a class="header-anchor" href="#_1-langchain" aria-label="Permalink to &quot;1. LangChain&quot;">​</a></h3><p>LangChain 提供用于构建 LLM 应用和 Agent 的开发组件。</p><p>它适合需要组合模型、工具、检索和外部服务的应用。</p><p>常见使用场景：</p><ul><li>为模型注册工具。</li><li>连接向量数据库和检索系统。</li><li>组合多个模型调用步骤。</li><li>构建带工具调用的 Agent。</li><li>集成不同模型供应商。</li></ul><p>它的主要价值是提供可复用的集成组件，减少重复开发。</p><p>需要注意：LangChain 不是一个自动解决所有任务的智能体。实际执行路径、状态管理、错误处理和权限控制仍然需要合理设计。</p><p>官方文档：<a href="https://docs.langchain.com/" target="_blank" rel="noreferrer">https://docs.langchain.com/</a></p><h3 id="_2-langgraph" tabindex="-1">2. LangGraph <a class="header-anchor" href="#_2-langgraph" aria-label="Permalink to &quot;2. LangGraph&quot;">​</a></h3><p>LangGraph 侧重于构建具有状态、分支、循环和持久化能力的多步骤 Agent 工作流。</p><p>它适合：</p><ul><li>需要多个执行阶段的任务。</li><li>需要根据中间结果进行分支决策。</li><li>需要保存执行状态。</li><li>需要暂停并等待人工审批。</li><li>需要处理中断、恢复和长时间运行任务。</li></ul><p>可以将它理解为帮助开发者组织复杂执行流程的工具。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开始</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>分析任务</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>执行工具</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>检查结果</span></span>
<span class="line"><span>  ├── 不满足条件 → 再次执行</span></span>
<span class="line"><span>  └── 满足条件 → 输出结果</span></span></code></pre></div><p>对于需要明确状态和恢复机制的系统，这类能力尤其有用。</p><p>官方文档：<a href="https://docs.langchain.com/oss/python/langgraph/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langgraph/overview</a></p><h3 id="_3-crewai" tabindex="-1">3. CrewAI <a class="header-anchor" href="#_3-crewai" aria-label="Permalink to &quot;3. CrewAI&quot;">​</a></h3><p>CrewAI 侧重于组织多个具有不同角色的 Agent 协作完成任务。</p><p>例如，构建一套研究流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>研究 Agent</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>分析 Agent</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>审核 Agent</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>报告生成</span></span></code></pre></div><p>不同 Agent 可以使用不同的指令、工具和职责。</p><p>适合考虑多角色任务分工的场景，例如资料研究、内容分析和多阶段报告生成。</p><p>不过，多 Agent 并不意味着任务一定更准确。</p><p>多个 Agent 会增加模型调用次数、通信成本和协调复杂度。对于简单任务，单 Agent 或确定性工作流可能更合适。</p><p>官方文档：<a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">https://docs.crewai.com/</a></p><h2 id="四、这些框架之间是什么关系" tabindex="-1">四、这些框架之间是什么关系？ <a class="header-anchor" href="#四、这些框架之间是什么关系" aria-label="Permalink to &quot;四、这些框架之间是什么关系？&quot;">​</a></h2><p>它们不是必须三选一的同类产品，也不代表只能按照某种固定方式组合。</p><table tabindex="0"><thead><tr><th>框架</th><th>主要关注点</th><th>适合考虑的场景</th></tr></thead><tbody><tr><td>LangChain</td><td>LLM 应用与工具集成</td><td>需要快速组合模型、工具和检索能力</td></tr><tr><td>LangGraph</td><td>状态化执行与工作流控制</td><td>需要分支、循环、持久化和恢复</td></tr><tr><td>CrewAI</td><td>多 Agent 角色协作</td><td>任务适合拆分为多个协作角色</td></tr></tbody></table><p>实际项目中，可以只使用其中一个，也可以组合不同组件。</p><p>选择时应先明确业务问题，再决定需要什么抽象，而不是为了使用框架而使用框架。</p><h2 id="五、自己写代码-还是使用框架" tabindex="-1">五、自己写代码，还是使用框架？ <a class="header-anchor" href="#五、自己写代码-还是使用框架" aria-label="Permalink to &quot;五、自己写代码，还是使用框架？&quot;">​</a></h2><h3 id="方案-a-自己实现最小-agent" tabindex="-1">方案 A：自己实现最小 Agent <a class="header-anchor" href="#方案-a-自己实现最小-agent" aria-label="Permalink to &quot;方案 A：自己实现最小 Agent&quot;">​</a></h3><p>基本结构如下：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> run_agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(task):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    messages </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: task}]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> call_model(messages)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.tool_calls:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">            return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.content</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tool_call </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> response.tool_calls:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> execute_allowed_tool(tool_call)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            messages.append(format_tool_result(tool_call, result))</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    raise</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> RuntimeError</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;超过最大执行次数&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>这是一个简化的伪代码示例，<code>call_model</code>、<code>execute_allowed_tool</code> 和 <code>format_tool_result</code> 需要自行实现。</p><p>优点：</p><ul><li>逻辑直接。</li><li>容易理解执行过程。</li><li>可以针对业务设计精确的限制。</li><li>依赖相对少。</li></ul><p>缺点：</p><ul><li>需要自行实现工具调度、状态管理、异常处理等能力。</li><li>功能扩展后可能积累大量基础设施代码。</li></ul><h3 id="方案-b-使用-agent-框架" tabindex="-1">方案 B：使用 Agent 框架 <a class="header-anchor" href="#方案-b-使用-agent-框架" aria-label="Permalink to &quot;方案 B：使用 Agent 框架&quot;">​</a></h3><p>优点：</p><ul><li>可以复用已有组件。</li><li>更容易构建复杂执行流程。</li><li>部分框架提供状态管理、追踪和人工介入机制。</li></ul><p>缺点：</p><ul><li>需要理解框架的抽象。</li><li>依赖升级可能影响实现。</li><li>调试时需要同时理解业务代码和框架行为。</li><li>框架提供的能力不一定符合所有业务需求。</li></ul><h2 id="六、如何选择合适的方案" tabindex="-1">六、如何选择合适的方案？ <a class="header-anchor" href="#六、如何选择合适的方案" aria-label="Permalink to &quot;六、如何选择合适的方案？&quot;">​</a></h2><p>可以按以下顺序判断。</p><h3 id="第一步-任务是否需要动态决策" tabindex="-1">第一步：任务是否需要动态决策？ <a class="header-anchor" href="#第一步-任务是否需要动态决策" aria-label="Permalink to &quot;第一步：任务是否需要动态决策？&quot;">​</a></h3><p>如果任务是固定的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收订单 → 校验订单 → 扣减库存 → 发送通知</span></span></code></pre></div><p>优先考虑确定性工作流。</p><p>如果任务需要根据中间结果调整下一步，例如多轮搜索和信息核验，可以考虑 Agent。</p><h3 id="第二步-执行流程是否复杂" tabindex="-1">第二步：执行流程是否复杂？ <a class="header-anchor" href="#第二步-执行流程是否复杂" aria-label="Permalink to &quot;第二步：执行流程是否复杂？&quot;">​</a></h3><p>如果只是一次工具调用，普通函数加模型 API 可能已经足够。</p><p>如果涉及大量分支、状态保存、暂停恢复和人工审批，可以考虑更完善的执行框架。</p><h3 id="第三步-是否需要多-agent-协作" tabindex="-1">第三步：是否需要多 Agent 协作？ <a class="header-anchor" href="#第三步-是否需要多-agent-协作" aria-label="Permalink to &quot;第三步：是否需要多 Agent 协作？&quot;">​</a></h3><p>先判断任务是否真的需要多个角色。</p><p>如果只是把同一任务拆成几个简单步骤，普通工作流可能更简单。</p><p>只有在角色职责、上下文或执行策略确实不同的情况下，才值得引入多 Agent 协作。</p><h3 id="第四步-安全和可靠性如何实现" tabindex="-1">第四步：安全和可靠性如何实现？ <a class="header-anchor" href="#第四步-安全和可靠性如何实现" aria-label="Permalink to &quot;第四步：安全和可靠性如何实现？&quot;">​</a></h3><p>无论选择哪种框架，都需要独立考虑：</p><ul><li>工具权限。</li><li>输入参数校验。</li><li>最大执行次数。</li><li>超时与重试。</li><li>成本和资源限制。</li><li>敏感操作审批。</li><li>日志与审计。</li><li>故障恢复。</li></ul><p>这些要求不能因为采用了成熟框架就自动视为已经满足。</p><h2 id="七、一个实用的工程原则" tabindex="-1">七、一个实用的工程原则 <a class="header-anchor" href="#七、一个实用的工程原则" aria-label="Permalink to &quot;七、一个实用的工程原则&quot;">​</a></h2><p>开发 Agent 时，可以从简单方案开始，逐步增加必要的复杂度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型 API</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>工具调用</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>带限制的执行循环</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>状态管理与错误恢复</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>复杂工作流</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>必要时再引入多 Agent</span></span></code></pre></div><p>每增加一层，都应该对应一个明确的问题和可验证的收益。</p><p>例如，只有在需要保存复杂状态、处理分支或恢复中断时，才考虑引入专门的状态化工作流框架。</p><h2 id="八、小结" tabindex="-1">八、小结 <a class="header-anchor" href="#八、小结" aria-label="Permalink to &quot;八、小结&quot;">​</a></h2><p>理解 Agent 框架，需要记住三个要点：</p><ol><li>框架是组织代码和执行流程的工具，不是 Agent 本身。</li><li>不同框架的关注点不同，应根据任务特点选择。</li><li>框架不能替代业务规则、安全控制和可靠性设计。</li></ol><p><strong>先把任务和执行边界设计清楚，再选择框架，通常比先选框架再寻找应用场景更有效。</strong></p><h2 id="下一篇" tabindex="-1">下一篇 <a class="header-anchor" href="#下一篇" aria-label="Permalink to &quot;下一篇&quot;">​</a></h2><p><a href="./agent-failure-modes">Agent 常见故障：幻觉、提示词注入、无限循环与重试风暴</a></p>`,91)])])}const k=s(l,[["render",p]]);export{g as __pageData,k as default};
